# LaTeX table bodies and number macros for model 4 (na_models_m4.R) and for the simulated confidence intervals (sim_ci_dance.R).
# Env: SRI_PROJECT_ROOT; NUM_DIR (manuscript numbers folder).
suppressMessages(library(data.table))
base <- Sys.getenv("SRI_PROJECT_ROOT"); numdir <- Sys.getenv("NUM_DIR")
x <- fread(file.path(base, "01_recompute_SRI/intermediate/revision_2026-10_results/model4/m4_all.csv"))
ethlab <- c("Mexican American" = "Mexican American", "Other Hispanic" = "Other Hispanic", "Non-Hispanic White" = "Non-Hispanic White", "Non-Hispanic Black" = "Non-Hispanic Black", "Non-Hispanic Asian" = "Non-Hispanic Asian", "Other Race - Including Multi-Racial" = "Other, incl. multiracial")
x[, eth := factor(eth, levels = names(ethlab))]; x[, sex := factor(sex, levels = c("Female", "Male"))]
cell <- function(mf, lo, hi) sprintf("%.3f (%.3f, %.3f)", mf, lo, hi)
# ---- Table: published sample, Phillips formula by input (published implementation for the published SRI) ----
inputs <- c(published = "Published SRI", raw = "Released, unsmoothed", maj1h50 = "Rolling majority", ggir1h80 = "GGIR SRI1 smoothing", bridge2 = "Bridged", spt2 = "Main sleep period")
g <- x[calculator %in% c("published implementation", "SRI_hand")][order(eth, sex)]
rows <- character()
for (e in levels(g$eth)) for (s in levels(g$sex)) { r <- g[eth == e & sex == s]
  vals <- sapply(names(inputs), function(i) { q <- r[input == i]; cell(q$mf, q$lo95, q$hi95) })
  rows <- c(rows, sprintf("%s & %s & %d & %s \\\\", if (s == "Female") ethlab[[e]] else "", if (s == "Female") "women" else "men", r[input == "published", N], paste(vals, collapse = " & "))) }
writeLines(c("% generated by m4_tables.R; do not edit", "\\begin{tabular}{llrcccccc}", "\\toprule",
             "Race/ethnicity & Sex & $n$ & Published SRI & Released, unsmoothed & Rolling majority & \\texttt{GGIR} SRI1 smoothing & Bridged & Main sleep period \\\\", "\\midrule",
             rows, "\\bottomrule", "\\end{tabular}"), file.path(numdir, "tab_model4_inputs.tex"))
# ---- Table: random sample, four series ----
ser <- c(PAXPREDM = "PAXPREDM", GGIR_SIB = "GGIR SIB", GGIR_SPT = "GGIR SPT", SWaN = "SWaN")
g2 <- x[input == "random sample"][order(eth, sex)]; rows2 <- character()
for (e in levels(g2$eth)) for (s in levels(g2$sex)) { r <- g2[eth == e & sex == s]
  vals <- sapply(names(ser), function(i) { q <- r[calculator == i]; cell(q$mf, q$lo95, q$hi95) })
  rows2 <- c(rows2, sprintf("%s & %s & %d & %s \\\\", if (s == "Female") ethlab[[e]] else "", if (s == "Female") "women" else "men", r[calculator == "PAXPREDM", N], paste(vals, collapse = " & "))) }
writeLines(c("% generated by m4_tables.R; do not edit", "\\begin{tabular}{llrcccc}", "\\toprule",
             "Race/ethnicity & Sex & $n$ & \\texttt{PAXPREDM} & \\texttt{GGIR} SIB & \\texttt{GGIR} SPT & SWaN \\\\", "\\midrule",
             rows2, "\\bottomrule", "\\end{tabular}"), file.path(numdir, "tab_model4_rawsample.tex"))
# ---- macros ----
mac <- character(); add <- function(nm, v) mac <<- c(mac, sprintf("\\newcommand{\\%s}{%s}", nm, v))
h <- x[calculator %in% c("published implementation", "SRI_hand")]
# calculator agreement on the same input (published sample): max |difference| of the 12 factors between the Phillips formula and GGIR / sleepreg
cal <- dcast(x[input %in% c("raw", "maj1h50", "ggir1h80", "bridge2", "spt2")], input + eth + sex ~ calculator, value.var = "mf")
add("mfourMaxDiffGgir", sprintf("%.3f", cal[, max(abs(SRI_GGIR - SRI_hand))])); add("mfourMaxDiffSleepregFive", sprintf("%.3f", cal[, max(abs(SRI_sleepregE5 - SRI_hand))])); add("mfourMaxDiffSleepregThree", sprintf("%.3f", cal[, max(abs(SRI_sleepregE3 - SRI_hand))]))
# women below men within every ethnicity, for every input (published sample, Phillips formula)?
w <- dcast(h, input + eth ~ sex, value.var = "mf"); add("mfourWomenBelowMen", sprintf("%d of %d", w[, sum(Female < Male)], nrow(w)))
# shift from the released to the smoothed inputs: range over the 12 groups of (smoothed - released)
sh <- dcast(h[input != "published"], eth + sex ~ input, value.var = "mf"); for (v in c("maj1h50", "ggir1h80", "bridge2", "spt2")) sh[, (v) := get(v) - raw]
rng <- range(unlist(sh[, .(maj1h50, ggir1h80, bridge2, spt2)])); add("mfourShiftLo", sprintf("%+.3f", rng[1])); add("mfourShiftHi", sprintf("%+.3f", rng[2]))
# key groups
key <- function(i, e, s) h[input == i & eth == e & sex == s]
for (nm in list(c("NhwWomenPub", "published", "Non-Hispanic White", "Female"), c("NhwWomenRel", "raw", "Non-Hispanic White", "Female"), c("NhwWomenSpt", "spt2", "Non-Hispanic White", "Female"),
                c("NhwMenPub", "published", "Non-Hispanic White", "Male"), c("NhwMenRel", "raw", "Non-Hispanic White", "Male"), c("NhwMenSpt", "spt2", "Non-Hispanic White", "Male"),
                c("NhbMenRel", "raw", "Non-Hispanic Black", "Male"), c("NhbMenSpt", "spt2", "Non-Hispanic Black", "Male"), c("MexMenRel", "raw", "Mexican American", "Male"), c("MexMenSpt", "spt2", "Mexican American", "Male"))) {
  q <- key(nm[2], nm[3], nm[4]); add(paste0("mfour", nm[1], "Est"), sprintf("%.3f", q$mf)); add(paste0("mfour", nm[1], "Lo"), sprintf("%.3f", q$lo95)); add(paste0("mfour", nm[1], "Hi"), sprintf("%.3f", q$hi95)) }
# smallest group and the group with a factor near one on the released series (named in the Results text)
for (nm in list(c("OthWomenPub", "published", "Other Race - Including Multi-Racial", "Female"), c("OthWomenRel", "raw", "Other Race - Including Multi-Racial", "Female"), c("OthWomenSpt", "spt2", "Other Race - Including Multi-Racial", "Female"),
                c("OthHispMenRel", "raw", "Other Hispanic", "Male"))) {
  q <- key(nm[2], nm[3], nm[4]); add(paste0("mfour", nm[1], "Est"), sprintf("%.3f", q$mf)); add(paste0("mfour", nm[1], "Lo"), sprintf("%.3f", q$lo95)); add(paste0("mfour", nm[1], "Hi"), sprintf("%.3f", q$hi95)) }
add("mfourOthWomenN", h[input == "published" & eth == "Other Race - Including Multi-Racial" & sex == "Female", N])
# published row versus the earlier study's Table 3 (bootstrap means there): max |difference| of the 12 point estimates
orig <- data.table(eth = rep(names(ethlab), each = 2), sex = rep(c("Male", "Female"), 6), orig = c(1.04, 0.98, 0.991, 0.934, 0.967, 0.91, 1.036, 0.975, 0.979, 0.922, 0.937, 0.882))
pub <- merge(h[input == "published", .(eth = as.character(eth), sex = as.character(sex), mf)], orig, by = c("eth", "sex")); add("mfourPubMaxDiffOrig", sprintf("%.3f", pub[, max(abs(mf - orig))]))
# random sample: group sizes
rs <- x[input == "random sample" & calculator == "PAXPREDM"]; add("mfourRawNmin", rs[, min(N)]); add("mfourRawNmax", rs[, max(N)])
rsw <- x[input == "random sample"]; add("mfourRawWidthMin", sprintf("%.2f", rsw[, min(hi95 - lo95)])); add("mfourRawWidthMax", sprintf("%.2f", rsw[, max(hi95 - lo95)]))   # interval widths over the 48 group factors
rw <- dcast(x[input == "random sample"], eth ~ sex + calculator, value.var = "mf")
add("mfourRawWomenBelowMenPaxpredm", sprintf("%d of 6", rw[, sum(Female_PAXPREDM < Male_PAXPREDM)])); add("mfourRawWomenBelowMenSwan", sprintf("%d of 6", rw[, sum(Female_SWaN < Male_SWaN)]))
add("mfourRawWomenBelowMenSib", sprintf("%d of 6", rw[, sum(Female_GGIR_SIB < Male_GGIR_SIB)])); add("mfourRawWomenBelowMenSpt", sprintf("%d of 6", rw[, sum(Female_GGIR_SPT < Male_GGIR_SPT)]))
# ---- simulated intervals ----
for (m in c("M2", "M3w")) { s <- fread(file.path(base, "01_recompute_SRI/intermediate/revision_2026-10_results/sim_ci_dance", paste0("sim_", m, ".csv"))); tr <- s$truth[1]; p <- if (m == "M2") "simTwo" else "simThreeW"
  add(paste0(p, "Truth"), sprintf("%.3f", tr)); add(paste0(p, "Nsim"), nrow(s)); add(paste0(p, "MfMin"), sprintf("%.3f", min(s$mf))); add(paste0(p, "MfMax"), sprintf("%.3f", max(s$mf)))
  add(paste0(p, "CoverNinetyFive"), s[, sum(lo95 <= tr & tr <= hi95)]); add(paste0(p, "CoverNinetyNine"), s[, sum(lo99 <= tr & tr <= hi99)])
  add(paste0(p, "WidthNinetyFive"), sprintf("%.3f", mean(s$hi95 - s$lo95))); add(paste0(p, "WidthNinetyNine"), sprintf("%.3f", mean(s$hi99 - s$lo99)))
  add(paste0(p, "LoMin"), sprintf("%.3f", min(s$lo95))); add(paste0(p, "HiMax"), sprintf("%.3f", max(s$hi95))); add(paste0(p, "AboveOne"), s[, sum(hi95 >= 1)]) }
writeLines(c("% generated by m4_tables.R; do not edit", mac), file.path(numdir, "model4_numbers.tex")); cat(mac, sep = "\n")
